const MOD = 998244353n;

function modPow(base, exp, mod) {
    base %= mod;
    if (base < 0n) base += mod;
    let result = 1n;
    while (exp > 0n) {
        if (exp % 2n === 1n) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp = exp / 2n;
    }
    return result;
}

function modInv(x, mod) {
    return modPow(x, mod - 2n, mod);
}

